import { Tracker, sampleAt, roadLengthM } from './engine.js';

const $ = id => document.getElementById(id);
const ui = Object.fromEntries(['clock','wakeButton','infoButton','infoDrawer','closeInfoButton','drawerBackdrop','modeBadge','signalText','signalDot','setupPanel','liveButton','demoButton','drivePanel','changeModeButton','roadRef','roadDirection','speedStatus','speedValue','speedTrackFill','limitValue','deltaValue','deltaTrend','deltaDescription','exitList','elapsedValue','accuracyValue','updatedValue','roadNote','demoControls','demoRoad','demoDirection','demoSpeed','demoSpeedOutput','demoPlayButton','networkText','coverageText','sourceText'].map(id => [id,$(id)]));
const STALE_MS = 15000;
let roadsData, tracker, mode = 'ready', watchId = null, staleTimer = null, demoTimer = null, demoRoad = null, demoChain = [], demoDistance = 0, demoClock = 0, lastDelta = null, demoPaused = false, lastFixTime = 0, wakeLock = null, lastFocus = null;
const roadList = () => roadsData?.roads || [];
const fmtTime = seconds => { const n=Math.max(0,Math.floor(seconds || 0)); return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`; };
const fmtDistance = m => m >= 1000 ? `${(m/1000).toFixed(m < 10000 ? 1 : 0)} km` : `${Math.max(0,Math.round(m/10)*10)} m`;
const fmtSigned = n => `${n < 0 ? '−' : '+'}${Math.abs(n).toFixed(1)}`;

function setSignal(message, tone='') { ui.signalText.textContent=message; ui.signalDot.className=`signal-dot ${tone}`; }
function setMode(next) { mode=next; ui.setupPanel.hidden=next!=='ready'; ui.drivePanel.hidden=next==='ready'; ui.demoControls.hidden=next!=='demo'; ui.modeBadge.textContent=next==='demo'?'DEMO · SIMULATED':next==='live'?'LIVE LOCATION':'READY'; ui.modeBadge.classList.toggle('demo',next==='demo'); }
function clearSession() { if(watchId!==null){navigator.geolocation?.clearWatch(watchId);watchId=null;} clearInterval(staleTimer);clearInterval(demoTimer);staleTimer=demoTimer=null; lastFixTime=0;lastDelta=null; tracker=roadsData?new Tracker(roadsData):null; demoPaused=false; ui.demoPlayButton.textContent='Pause demo'; }
function resetDashboard() { ui.roadRef.textContent='—';ui.roadDirection.textContent='Locating road';ui.speedValue.textContent='—';ui.speedStatus.textContent='—';ui.speedTrackFill.style.width='0%';ui.limitValue.textContent='UNKNOWN';ui.deltaValue.textContent='—';ui.deltaValue.classList.remove('behind');ui.deltaTrend.textContent='→';ui.deltaTrend.setAttribute('aria-label','Pace trend steady');ui.deltaDescription.textContent='Waiting for a known road limit';ui.exitList.innerHTML='<li class="empty-exits">Upcoming exits will appear when the road is identified.</li>';ui.elapsedValue.textContent='00:00';ui.accuracyValue.textContent='—';ui.updatedValue.textContent='—';ui.roadNote.textContent='Road and speed data may be incomplete. Follow signs and road conditions.'; }
function render(state, fix) {
  const road=state?.road;
  ui.roadRef.textContent=road?.ref||'—';
  ui.roadDirection.textContent=road ? [road.direction,road.name].filter(Boolean).join(' · ') : (state?.status==='gap'?'Outside mapped coverage':'Locating road');
  ui.speedValue.textContent=Number.isFinite(state?.speedKmh)?Math.round(state.speedKmh):'—';
  ui.speedStatus.textContent=state?.status==='tracking'?`TRACKING · ${(state.confidence||'unknown').toUpperCase()}`:(state?.status||'SEARCHING').toUpperCase();
  ui.limitValue.textContent=Number.isFinite(state?.limitKmh)?`${Math.round(state.limitKmh)} KM/H`:'UNKNOWN';
  ui.speedTrackFill.style.width=Number.isFinite(state?.speedKmh)?`${Math.min(100,Math.max(0,state.speedKmh/120*100))}%`:'0%';
  const delta=state?.deltaSeconds;
  ui.deltaValue.textContent=Number.isFinite(delta)?fmtSigned(delta):'—';
  ui.deltaValue.style.setProperty('--delta-scale', String(Math.min(1,4/ui.deltaValue.textContent.length)));
  ui.deltaValue.classList.toggle('behind',Number.isFinite(delta)&&delta<0);if(Number.isFinite(delta)&&Number.isFinite(lastDelta)){const trend=delta-lastDelta;ui.deltaTrend.textContent=trend>.15?'↑':trend<-.15?'↓':'→';ui.deltaTrend.setAttribute('aria-label',trend>.15?'Pace delta rising':trend<-.15?'Pace delta falling':'Pace trend steady');}lastDelta=Number.isFinite(delta)?delta:null;
  ui.deltaDescription.textContent=Number.isFinite(delta)?delta<0?'Ahead of reference pace · ease off if needed':delta>0?'Behind reference pace':'At reference pace':Number.isFinite(state?.limitKmh)?'Waiting for a stable road match':'No known reference limit for this road';
  ui.elapsedValue.textContent=fmtTime(state?.elapsedSeconds);
  ui.accuracyValue.textContent=Number.isFinite(fix?.accuracy)?`±${Math.round(fix.accuracy)} m`:'—';
  ui.updatedValue.textContent=fix?.timestamp?new Date(fix.timestamp).toLocaleTimeString('en-SG',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}):'—';
  const exits=(state?.exits||[]).slice(0,3);
  ui.exitList.replaceChildren();
  if(!exits.length){const li=document.createElement('li');li.className='empty-exits';li.textContent=road?'No mapped exits ahead in this segment.':'Upcoming exits will appear when the road is identified.';ui.exitList.append(li);}
  for(const exit of exits){const li=document.createElement('li');const name=document.createElement('span');name.className='exit-name';name.textContent=exit.name||exit.ref||'Exit';const dist=document.createElement('span');dist.className='exit-distance';dist.textContent=Number.isFinite(exit.distanceM)?fmtDistance(exit.distanceM):'—';const deltaEl=document.createElement('span');deltaEl.className='exit-delta';deltaEl.textContent=Number.isFinite(exit.projectedDeltaSeconds)?`${fmtSigned(exit.projectedDeltaSeconds)}s est.`:'—';if(exit.projectedDeltaSeconds<0)deltaEl.style.color='#ffbd80';li.append(name,dist,deltaEl);ui.exitList.append(li);}
  ui.roadNote.textContent=state?.reason||'Road and speed data may be incomplete. Follow signs and road conditions.';
  if(mode==='live') setSignal(state?.status==='tracking'?'Live location · road matched':state?.status==='gap'?'Live location · coverage gap':'Live location · locating road',state?.status==='tracking'?'good':'warn');
}
function onFix(position){ if(mode!=='live')return; const c=position.coords;const fix={latitude:c.latitude,longitude:c.longitude,accuracy:c.accuracy,heading:c.heading,speed:c.speed,timestamp:position.timestamp};lastFixTime=Date.now();try{render(tracker.update(fix),fix);}catch(err){setSignal('Road data unavailable','warn');console.error(err);} }
function invalidateLocation(message){tracker?.invalidate(message);resetDashboard();ui.speedStatus.textContent='NO SIGNAL';ui.roadDirection.textContent=message;setSignal(message,'warn');}
function onLocationError(err){ if(mode!=='live')return;const text=err.code===1?'Location permission denied':err.code===2?'Location temporarily unavailable':'Location timed out';invalidateLocation(text); }
function startLive(){clearSession();resetDashboard();setMode('live');setSignal('Requesting precise location…','warn');if(!roadsData){setSignal('Road data unavailable','warn');return;}if(!navigator.geolocation){setSignal('Location unavailable in this browser','warn');return;}watchId=navigator.geolocation.watchPosition(onFix,onLocationError,{enableHighAccuracy:true,maximumAge:0,timeout:12000});staleTimer=setInterval(()=>{if(mode==='live'&&lastFixTime&&Date.now()-lastFixTime>STALE_MS){lastFixTime=0;invalidateLocation('Location stale · waiting for signal');ui.speedStatus.textContent='STALE';}},1000);requestWake();}
function roadKey(road){return road.id||`${road.ref}|${road.direction}|${road.name}`;}
function buildDemoChains(ref){const byId=new Map(roadList().map(r=>[r.id,r]));return (roadsData.chains||[]).filter(c=>c.ref===ref).sort((a,b)=>b.lengthM-a.lengthM).slice(0,2).map(meta=>{const chain=[],seen=new Set();let road=byId.get(meta.firstRoadId);while(road&&!seen.has(road.id)&&road.chainId===meta.id){chain.push(road);seen.add(road.id);road=byId.get(road.nextRoadIds?.[0]);}chain.demoDirection=meta.travelDirection;return chain;});}
function populateDemo(){const refs=[...new Set(roadList().map(r=>r.ref).filter(Boolean))].sort();ui.demoRoad.replaceChildren(...refs.map(ref=>new Option(ref,ref)));if(refs.includes('BKE'))ui.demoRoad.value='BKE';updateDemoDirections();}
function updateDemoDirections(){const chains=buildDemoChains(ui.demoRoad.value);ui.demoDirection.replaceChildren(...chains.map((chain,i)=>new Option(`${{N:'Northbound',S:'Southbound',E:'Eastbound',W:'Westbound'}[chain.demoDirection]||'Direction'} · ${Math.round(chain.reduce((n,r)=>n+roadLengthM(r),0)/1000)} km`,String(i))));ui.demoDirection._chains=chains;selectDemoRoad();}
function selectDemoRoad(){demoChain=ui.demoDirection._chains?.[Number(ui.demoDirection.value)]||[];demoRoad=demoChain[0]||null;demoDistance=0;demoClock=Date.now();tracker=new Tracker(roadsData);lastDelta=null;tickDemo(0);}
function tickDemo(seconds=1){if(mode!=='demo'||!demoRoad||demoPaused)return;const speed=Number(ui.demoSpeed.value);ui.demoSpeedOutput.value=`${speed} km/h`;const length=demoChain.reduce((n,r)=>n+roadLengthM(r),0);if(Number.isFinite(length)&&length>0)demoDistance=(demoDistance+speed/3.6*seconds)%length;let remaining=demoDistance,segment=demoChain[0];for(const road of demoChain){const n=roadLengthM(road);if(remaining<=n){segment=road;break;}remaining-=n;}const point=sampleAt(segment,remaining);if(!point)return;if(seconds>0)demoClock+=seconds*1000;const fix={...point,accuracy:5,speed:speed/3.6,timestamp:demoClock};try{render(tracker.update(fix),fix);}catch(err){setSignal('Demo road unavailable','warn');console.error(err);}setSignal('DEMO · simulated location','good');}
function startDemo(){clearSession();resetDashboard();setMode('demo');if(!roadsData){setSignal('Road data unavailable','warn');return;}populateDemo();tickDemo(0);demoTimer=setInterval(()=>tickDemo(1),1000);}
function showReady(){clearSession();setMode('ready');setSignal('Choose a mode to begin');resetDashboard();}
async function requestWake(){if(!('wakeLock'in navigator)||document.visibilityState!=='visible'||mode==='ready')return;try{wakeLock=await navigator.wakeLock.request('screen');ui.wakeButton.setAttribute('aria-pressed','true');wakeLock.addEventListener('release',()=>{wakeLock=null;ui.wakeButton.setAttribute('aria-pressed','false');});}catch{ui.wakeButton.setAttribute('aria-pressed','false');}}
async function toggleWake(){if(wakeLock){await wakeLock.release();wakeLock=null;}else await requestWake();}
function openInfo(){lastFocus=document.activeElement;ui.drawerBackdrop.hidden=false;ui.infoDrawer.hidden=false;ui.infoButton.setAttribute('aria-expanded','true');ui.infoDrawer.focus();}
function closeInfo(){ui.drawerBackdrop.hidden=true;ui.infoDrawer.hidden=true;ui.infoButton.setAttribute('aria-expanded','false');lastFocus?.focus();}
function initEvents(){ui.liveButton.addEventListener('click',startLive);ui.demoButton.addEventListener('click',startDemo);ui.changeModeButton.addEventListener('click',showReady);ui.demoRoad.addEventListener('change',updateDemoDirections);ui.demoDirection.addEventListener('change',selectDemoRoad);ui.demoSpeed.addEventListener('input',()=>{ui.demoSpeedOutput.value=`${ui.demoSpeed.value} km/h`;tickDemo(0);});ui.demoPlayButton.addEventListener('click',()=>{demoPaused=!demoPaused;ui.demoPlayButton.textContent=demoPaused?'Resume demo':'Pause demo';setSignal(demoPaused?'DEMO · paused':'DEMO · simulated location',demoPaused?'warn':'good');});ui.wakeButton.addEventListener('click',toggleWake);ui.infoButton.addEventListener('click',openInfo);ui.closeInfoButton.addEventListener('click',closeInfo);ui.drawerBackdrop.addEventListener('click',closeInfo);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!ui.infoDrawer.hidden)closeInfo();if(e.key==='Tab'&&!ui.infoDrawer.hidden){const focusable=[...ui.infoDrawer.querySelectorAll('button,a,[tabindex]:not([tabindex="-1"])')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0]?.focus();}}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&mode!=='ready'&&!wakeLock)requestWake();});window.addEventListener('pagehide',()=>{clearSession();wakeLock?.release();});window.addEventListener('online',updateNetwork);window.addEventListener('offline',updateNetwork);}
function updateNetwork(){ui.networkText.textContent=navigator.onLine?'LOCAL SESSION':'OFFLINE · LOCAL SESSION';}
function updateClock(){ui.clock.textContent=new Date().toLocaleTimeString('en-SG',{hour:'2-digit',minute:'2-digit',hour12:false});}
async function init(){initEvents();updateClock();setInterval(updateClock,15000);updateNetwork();try{const response=await fetch('./data/roads.json');if(!response.ok)throw new Error(`Road data ${response.status}`);roadsData=await response.json();tracker=new Tracker(roadsData);const meta=roadsData.metadata||{};ui.coverageText.textContent=`Coverage includes ${new Set(roadList().map(r=>r.ref)).size} expressway references and ${roadList().length} mapped direction segments. Speed limits and exit locations may be missing or outdated. Unknown limits stay unknown; pace delta appears only with a known reference.`;ui.sourceText.textContent=`Road data: ${meta.sourceAttribution||'© OpenStreetMap contributors'} · ${meta.license||'ODbL-1.0'}. ${meta.note||'Map data may be incomplete.'}`;startLive();}catch(err){console.error(err);setSignal('Road data unavailable','warn');}if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
init();
